theorem isRoot_of_iterate_ne {S : Type*} [CommRing S] [IsDomain S] {f g A B : R₀[X]}
    {n m N : ℕ} (hgAB : g = A * B) (hB : B ∣ (P f n - P f m) ^ N) (ψ : R₀ →+* S) {c : S}
    (hc : (g.map ψ).IsRoot c)
    (hnm : (fun z => (f.map ψ).eval z)^[n] c ≠ (fun z => (f.map ψ).eval z)^[m] c) :
    (A.map ψ).IsRoot c

theorem HouseLE.mul {x y : ℂ} {M N : ℝ}
    (hx : HouseLE x M) (hy : HouseLE y N)
    (hxi : IsIntegral ℚ x) (hyi : IsIntegral ℚ y) : HouseLE (x * y) (M * N)

theorem IsBoundedAlgInt.mul {x y : ℂ} {M N : ℝ}
    (hx : IsBoundedAlgInt M x) (hy : IsBoundedAlgInt N y) :
    IsBoundedAlgInt (M * N) (x * y)

theorem norm_eval_ge {f : ℂ[X]} (hf : f.Monic) (hd : 2 ≤ f.natDegree) {B : ℝ} (hB : 1 ≤ B)
    (hcoef : ∀ k < f.natDegree, ‖f.coeff k‖ ≤ B) {z : ℂ}
    (hz : 2 * f.natDegree * B ≤ ‖z‖) : 2 * ‖z‖ ≤ ‖f.eval z‖

theorem norm_iterate_of_escape {f : ℂ[X]} (hf : f.Monic) (hd : 2 ≤ f.natDegree) {B : ℝ}
    (hB : 1 ≤ B) (hcoef : ∀ k < f.natDegree, ‖f.coeff k‖ ≤ B) {z : ℂ}
    (hz : 2 * f.natDegree * B ≤ ‖z‖) :
    ∀ m, 2 * f.natDegree * B ≤ ‖(fun w => f.eval w)^[m] z‖ ∧
      ‖(fun w => f.eval w)^[m] z‖ < ‖(fun w => f.eval w)^[m + 1] z‖

theorem not_hasFiniteOrbit_of_escape_arch {f : ℂ[X]} (hf : f.Monic) (hd : 2 ≤ f.natDegree)
    {B : ℝ} (hB : 1 ≤ B) (hcoef : ∀ k < f.natDegree, ‖f.coeff k‖ ≤ B) {z : ℂ}
    (hz : 2 * f.natDegree * B ≤ ‖z‖) : ¬ HasFiniteOrbit f z

theorem not_hasFiniteOrbit_of_escape {f : F[X]} (hf : f.Monic) (hd : 2 ≤ f.natDegree) {B : Γ₀}
    (hB : 1 ≤ B) (hcoef : ∀ k < f.natDegree, v (f.coeff k) ≤ B) {z : F} (hz : B < v z) :
    ¬ HasFiniteOrbit f z

theorem val_iterate_le_of_hasFiniteOrbit {f : F[X]} (hf : f.Monic) (hd : 2 ≤ f.natDegree)
    {B : Γ₀} (hB : 1 ≤ B) (hcoef : ∀ k < f.natDegree, v (f.coeff k) ≤ B) {c : F}
    (hc : HasFiniteOrbit f c) (n : ℕ) : v ((fun w => f.eval w)^[n] c) ≤ B

theorem nonConst_of_isExceptional {d r : ℕ} {K : IntermediateField ℚ ℂ}
    {a : Fin (d - 1) → AddMonoidAlgebra K (Fin r → ℤ)} {T : Set (Fin r → ℂˣ)}
    (hEx : IsExceptional d K r a T) :
    ∃ i, MvLaurent.NonConst (AddMonoidAlgebra.mapRingHom (Fin r → ℤ) K.val.toRingHom (a i))

theorem loxton_step {B : ℝ} (hB : 1 ≤ B) {Λ' : ℕ}
    (hΛ' : ∀ P, 0 < P → ∀ β ∈ cycInt P, cassM P β ≤ B - 1 / 2 → β ∈ SumRoots Λ') :
    ∃ Λ : ℕ, ∀ P, 0 < P → ∀ β ∈ cycInt P, cassM P β ≤ B → β ∈ SumRoots Λ
